public class FolderTreeTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.function.Supplier<Object> call) {
        Object actual;
        try {
            actual = call.get();
        } catch (Throwable t) {
            actual = "threw " + t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    static void done() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static FolderTree leaf() {
        return new FolderTree("docs", List.of(new FileEntry("a.txt", 10)), List.of());
    }

    static FolderTree tree() {
        FolderTree images = new FolderTree("images",
                List.of(new FileEntry("logo.png", 40), new FileEntry("icon.png", 2)), List.of());
        FolderTree drafts = new FolderTree("drafts",
                List.of(new FileEntry("v1.md", 3)), List.of(images));
        FolderTree empty = new FolderTree("empty", List.of(), List.of());
        return new FolderTree("root",
                List.of(new FileEntry("readme.md", 5)), List.of(drafts, empty));
    }

    public static void main(String[] args) {
        FolderTree empty = new FolderTree("empty", List.of(), List.of());
