        check("empty folder count", 0, empty.fileCount());
        check("empty folder depth", 1, empty.depth());

        check("leaf folder size", 10, leaf().totalSizeKb());
        check("leaf folder count", 1, leaf().fileCount());
        check("leaf folder depth", 1, leaf().depth());

        FolderTree root = tree();
        check("nested total size", 50, root.totalSizeKb());
        check("nested file count", 4, root.fileCount());
        check("nested depth", 3, root.depth());

        FolderTree mid = root.subfolders().get(0);
        check("sub-folder total size", 45, mid.totalSizeKb());
        check("sub-folder depth", 2, mid.depth());
        done();
