import java.util.List;

/**
 * TASK: Complete the FolderTree record. The FileEntry record above it is
 * provided -- do not edit it.
 *
 * A FolderTree holds files and sub-folders, so it is a small tree built
 * entirely out of records.
 *
 * - totalSizeKb() adds up every file in this folder AND in every sub-folder,
 *   however deep.
 * - fileCount() counts every file in this folder and in every sub-folder.
 * - depth() is 1 for a folder with no sub-folders, and otherwise
 *   1 + the largest depth among its sub-folders.
 *
 * Example: a folder holding one 10 KB file and one sub-folder holding a 5 KB
 * file has totalSizeKb() 15, fileCount() 2 and depth() 2.
 */
record FileEntry(String name, int sizeKb) { }

public record FolderTree(String name, List<FileEntry> files, List<FolderTree> subfolders) {

    public int totalSizeKb() {
        int total = 0;
        for (FileEntry file : files) {
            total += file.sizeKb();
        }
        for (FolderTree sub : subfolders) {
            total += sub.totalSizeKb();
        }
        return total;
    }

    public int fileCount() {
        int count = files.size();
        for (FolderTree sub : subfolders) {
            count += sub.fileCount();
        }
        return count;
    }

    public int depth() {
        int deepestChild = 0;
        for (FolderTree sub : subfolders) {
            deepestChild = Math.max(deepestChild, sub.depth());
        }
        return 1 + deepestChild;
    }
}
